    for scope, diag in data["diagnostics"].items():
        lines += ["", f"{scope}: межсемейных пар {diag['cross_family_pairs']}; совпадающих условий по текущему контракту {diag['applicability_equal_pairs']}.", "", "```json", json.dumps(diag["difference_counts"], ensure_ascii=False, indent=2), "```"]
    lines += ["", "## Следующий шаг", "", "Разложить контекст на проверяемые признаки возраста/MCI, исключения деменции, шкалы/события, экспозиции/контраста, срока и поправок. Проверить правила переноса на этих же источниках до расширения корпуса. Нельзя считать смену описания контекста переносом, доказанным данными.", "",
              "Для правила нужен минимум двух независимых исторических семей заключений до удержанного результата; число семей всего корпуса недостаточно. В основных хронологических разбиениях для подходящих целей доступно 0, 1 или 2 подходящих обучающих семьи; в sensitivity — 0, 1, 2 или 3, но их условия различаются.", "",
              "Отказы сохранились в обеих ветках. Новая будущая цель не читалась. Экспертная научная проверка отсутствует. Старые GOLD, карты в UI и неизменяемые запуски сохранены."]
    folder = Path(folder)
    write_immutable(folder / "review.json", FilePredictionStore.encode(data))
    write_immutable(folder / "report.html", html.encode("utf-8"))
    write_immutable(folder / "report.ru.md", ("\n".join(lines) + "\n").encode("utf-8"))
